def _is_post_admission_rejection(
    self, profile: AgentProfile, failure: ProviderFailure
) -> bool:
    if failure.condition != "provider_rejected" or failure.status_code != 404:
        return False
    last_req = getattr(self, '_last_failed_request', None)
    if last_req is not None:
        key = self._route_key(
            last_req.provider,
            last_req.base_url,
            last_req.model,
        )
    else:
        # When we lack the failed request (e.g., in unit tests), fall back to
        # the profile's expected route.
        key = self._route_key(
            profile.model.provider,
            profile.model.base_url,
            profile.model.model,
        )
    return key in self._routes_proven
